ST.xhtml:
tgt := INT_TO_REAL(pos_target);
IF NOT Busy AND ABS(tgt - pos) > POSWIN THEN
    Busy := TRUE;
    Done := FALSE;
END_IF;
IF hold_req THEN
    IF vel > 0.0 THEN vel := MAX(0.0, vel - ACCEL * SCAN_T);
    ELSIF vel < 0.0 THEN vel := MIN(0.0, vel + ACCEL * SCAN_T);
    END_IF;
ELSIF Busy THEN
    dist := tgt - pos;
    stop_d := (vel * vel) / (2.0 * ACCEL);
    IF ABS(dist) <= stop_d THEN
        IF dist >= 0.0 THEN vel := MAX(0.0, vel - ACCEL * SCAN_T);
        ELSE vel := MIN(0.0, vel + ACCEL * SCAN_T);
        END_IF;
        IF vel = 0.0 AND ABS(dist) <= POSWIN THEN
            pos := tgt; Busy := FALSE; Done := TRUE;
        END_IF;
    ELSE
        IF dist > 0.0 THEN vel := MIN(VMAX, vel + ACCEL * SCAN_T);
        ELSE vel := MAX(-VMAX, vel - ACCEL * SCAN_T);
        END_IF;
    END_IF;
END_IF;
pos := pos + vel * SCAN_T;
Setpoint := REAL_TO_INT(pos);

prog_id := 5;
IF cmd_home THEN
    x_tgt := 0; tt_tgt := 0; el_tgt := 0;
END_IF;
el_hold := quickstop OR (el_tgt < 0) OR (el_tgt > 270);

(* X 直线轴 + 肘有限旋转轴: 共用 INTERP FB *)
ix_x(pos_target := x_tgt, hold_req := quickstop);
x_cmd := ix_x.Setpoint;
ix_el(pos_target := el_tgt, hold_req := el_hold);
el_cmd := ix_el.Setpoint;

(* 转盘环形轴: 插补逻辑内联(环形回绕 + 最短路径) *)
ttv_tgt := INT_TO_REAL(tt_tgt);
IF NOT ttv_busy AND ABS(ttv_tgt - ttv_pos) > 3.0 THEN
    ttv_busy := TRUE;
    ttv_done := FALSE;
END_IF;
ttv_dist := ttv_tgt - ttv_pos;
IF ttv_dist > 180.0 THEN ttv_dist := ttv_dist - 360.0; END_IF;
IF ttv_dist < -180.0 THEN ttv_dist := ttv_dist + 360.0; END_IF;
IF quickstop THEN
    IF ttv_vel > 0.0 THEN ttv_vel := MAX(0.0, ttv_vel - 90.0 * 0.02);
    ELSIF ttv_vel < 0.0 THEN ttv_vel := MIN(0.0, ttv_vel + 90.0 * 0.02);
    END_IF;
ELSIF ttv_busy THEN
    ttv_stop := (ttv_vel * ttv_vel) / 360.0;
    IF ABS(ttv_dist) <= ttv_stop THEN
        IF ttv_dist >= 0.0 THEN ttv_vel := MAX(0.0, ttv_vel - 3.6);
        ELSE ttv_vel := MIN(0.0, ttv_vel + 3.6);
        END_IF;
        IF ttv_vel = 0.0 AND ABS(ttv_dist) <= 3.0 THEN
            ttv_pos := ttv_tgt; ttv_busy := FALSE; ttv_done := TRUE;
        END_IF;
    ELSE
        IF ttv_dist > 0.0 THEN ttv_vel := MIN(90.0, ttv_vel + 3.6);
        ELSE ttv_vel := MAX(-90.0, ttv_vel - 3.6);
        END_IF;
    END_IF;
END_IF;
ttv_pos := ttv_pos + ttv_vel * 0.02;
IF ttv_pos >= 360.0 THEN ttv_pos := ttv_pos - 360.0; END_IF;
IF ttv_pos < 0.0 THEN ttv_pos := ttv_pos + 360.0; END_IF;
tt_cmd := REAL_TO_INT(ttv_pos);
tt_done := ttv_done;
tt_busy := ttv_busy;

(* 状态 *)
move_done := ix_x.Done AND ttv_done AND ix_el.Done;
any_moving := ix_x.Busy OR ttv_busy OR ix_el.Busy;
